import crypto from 'node:crypto';
import { URL } from 'node:url';

const TRACKING = /^(utm_|fbclid$|gclid$|mc_|ref$|source$)/i;
const PRIVATE = /(^localhost$|\.local$|\.internal$|^127\.|^10\.|^0\.|^169\.254\.|^192\.168\.|^172\.(1[6-9]|2\d|3[01])\.)/;
export function normalizeUrl(input) { const url = new URL(input); if (!/^https?:$/.test(url.protocol)) throw new Error('Only http(s) URLs are allowed'); if (PRIVATE.test(url.hostname)) throw new Error('Private and local network URLs are blocked'); url.hash = ''; for (const key of [...url.searchParams.keys()]) if (TRACKING.test(key)) url.searchParams.delete(key); if (url.pathname !== '/') url.pathname = url.pathname.replace(/\/+$/, ''); return url.toString(); }
export function canonicalFromHtml(html, base) { const match = html.match(/<link\b[^>]*\brel=["']canonical["'][^>]*\bhref=["']([^"']+)["']/i) || html.match(/<link\b[^>]*\bhref=["']([^"']+)["'][^>]*\brel=["']canonical["']/i); try { return match ? normalizeUrl(new URL(match[1], base).href) : normalizeUrl(base); } catch { return normalizeUrl(base); } }
const decode = value => value.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
const tag = (block, name) => decode((block.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`, 'i')) || [,''])[1]);
export function parseFeed(xml, sourceId) { const blocks = xml.match(/<(?:item|entry)\b[\s\S]*?<\/(?:item|entry)>/gi) || []; return blocks.map(block => { const link = (block.match(/<link[^>]+href=["']([^"']+)["']/i) || [,''])[1] || tag(block, 'link'); if (!link) return null; try { return { id: crypto.createHash('sha256').update(normalizeUrl(link)).digest('hex'), source_id: sourceId, url: normalizeUrl(link), title: tag(block, 'title'), description: tag(block, 'description') || tag(block, 'summary'), published_at: tag(block, 'pubDate') || tag(block, 'published') || null, author: tag(block, 'author') || null, raw: block }; } catch { return null; } }).filter(Boolean); }
export function parseSitemap(xml, sourceId) { return [...xml.matchAll(/<url>[\s\S]*?<loc>([\s\S]*?)<\/loc>[\s\S]*?(?:<lastmod>([\s\S]*?)<\/lastmod>)?[\s\S]*?<\/url>/gi)].map(match => { try { return { id: crypto.createHash('sha256').update(normalizeUrl(decode(match[1]))).digest('hex'), source_id: sourceId, url: normalizeUrl(decode(match[1])), title: '', description: '', published_at: decode(match[2] || '') || null, author: null, raw: match[0] }; } catch { return null; } }).filter(Boolean); }
export function extractLinks(html, base, sourceId) { return [...html.matchAll(/<a\b[^>]*\bhref=["']([^"'#]+)["']/gi)].map(match => { try { const url = normalizeUrl(new URL(match[1], base).href); return { id: crypto.createHash('sha256').update(url).digest('hex'), source_id: sourceId, url, title: '', description: '', published_at: null, author: null, raw: match[0] }; } catch { return null; } }).filter(Boolean); }
export function titleKey(title = '') { return title.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(word => word.length > 2).sort().join(' '); }
export function clusterCandidates(candidates) { const groups = new Map(); for (const item of candidates) { const key = item.canonical_url || item.url || titleKey(item.title); if (!groups.has(key)) groups.set(key, []); groups.get(key).push(item); } return [...groups.values()].map(items => ({ id: crypto.createHash('sha256').update(items.map(x => x.url).sort().join('|')).digest('hex').slice(0, 24), title: items.find(x => x.title)?.title || '', candidates: items, evidence: { canonical_urls: [...new Set(items.map(x => x.canonical_url || x.url))], titles: [...new Set(items.map(x => titleKey(x.title)))], source_count: new Set(items.map(x => x.source_id)).size } })); }
export function detectPaywall(html, status) { return status === 402 || /subscribe to continue|enable javascript to continue|sign in to continue reading|paywall/i.test(html); }
export function extractReadableText(html) { return html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<nav[\s\S]*?<\/nav>|<footer[\s\S]*?<\/footer>|<aside[\s\S]*?<\/aside>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
export async function fetchDocument(url, { fetchImpl = fetch, maxBytes = 2_000_000, timeoutMs = 20_000 } = {}) { const safe = normalizeUrl(url); const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), timeoutMs); try { const response = await fetchImpl(safe, { signal: controller.signal, redirect: 'follow', headers: { 'user-agent': 'AnywaysLocalResearch/1.0 (+local operator)' } }); const type = response.headers.get('content-type') || ''; if (!response.ok) return { ok: false, url: safe, status: response.status, error: `HTTP ${response.status}` }; if (!/text\/html|application\/xml|text\/xml|application\/rss\+xml|application\/pdf/i.test(type)) return { ok: false, url: safe, status: response.status, error: `unsupported content type: ${type}` }; const text = await response.text(); if (Buffer.byteLength(text) > maxBytes) return { ok: false, url: safe, status: response.status, error: 'document exceeds size limit' }; const paywalled = detectPaywall(text, response.status); return { ok: !paywalled, url: safe, status: response.status, content_type: type, raw: text, canonical_url: /html/i.test(type) ? canonicalFromHtml(text, safe) : safe, text: /html/i.test(type) ? extractReadableText(text) : text, paywalled, fetched_at: new Date().toISOString() }; } finally { clearTimeout(timer); } }
